  a=np.asarray(Image.open(f).convert('RGBA')).astype(np.int16);R,G,V=a[:,:,:3][a[:,:,3]>=240].T
  bands=dict(magenta=np.minimum(R,V)-G,green=G-np.maximum(R,V),blue=V-np.maximum(R,G),cyan=np.minimum(G,V)-R)
